//MSSCUSTODY-7230
function hasAssignedToChanged(task) {
    var audit = new GlideRecord('sys_audit');
    audit.addQuery('documentkey', task.sys_id);
    audit.addQuery('fieldname', 'assigned_to');
    audit.orderByDesc('sys_created_on');
    audit.setLimit(1);
    audit.query();

    if (audit.next()) {
        var oldVal = audit.getValue('oldvalue');
        if (!oldVal) return false;
        var newVal = audit.getValue('newvalue');
        return oldVal != newVal;
    }
    return false;
}


if (typeof window == 'undefined') {

    var gURI = new GlideURI();
    var sys_param = current.getValue('sys_id');
    var list_query = gURI.get('sysparm_record_list');
    //	gs.info('filtered list '+ list_query );
    var number_rows = gURI.get('sysparm_record_rows');
    //	gs.info('rows ' + number_rows);
    var host = gs.getProperty("glide.servlet.uri");
    var user = gs.getUserID();

    var session = gs.getSession();
    session.putClientData('skip_ids', null);
    var clientData = session.getClientData('skip_ids');

    //MSSCUSTODY-7230
    if (!(current.state == 2 && hasAssignedToChanged(current))) {
        current.lock = false;
        current.assigned_to = "";
        current.state = 1;
        current.update();
    }

    action.setRedirectURL(host + 'x_hsb11_mss_c_proc_mss_custody_task_list.do?sysparm_query=' + list_query);


}
